<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot\Views; use Pterodactyl\Services\Dezerx\DiscordBot\Ui; use Pterodactyl\Services\Dezerx\DiscordBot\Style; use Pterodactyl\Services\Dezerx\DiscordBot\Format; use Pterodactyl\Services\Dezerx\DiscordBot\Servers; use Pterodactyl\Services\Dezerx\DiscordBot\ClientApi; class Backups { public static function list(ClientApi $api, string $identifier, ?string $notice = null): array { $found = Servers::find($api, $identifier); if ($found['server'] === null) { return Cards::error($found['error']); } $server = $found['server']; $response = $api->get('servers/' . $server['id'] . '/backups', ['per_page' => 25]); if (!$response->ok()) { return Cards::error($response->error(), self::back($server['id'])); } $backups = $response->items(); return self::composeList($server, $backups, (int) $response->meta('backup_count', count($backups)), $notice); } public static function composeList(array $server, array $backups, int $count, ?string $notice = null): array { $style = Style::current(); $id = $server['id']; $limit = $server['backup_limit']; $full = $limit > 0 && $count >= $limit; $lines = array_map(fn (array $backup) => self::line($backup), array_slice($backups, 0, 12)); if (count($backups) > 12) { $lines[] = '-# …and ' . (count($backups) - 12) . ' more. Pick one from the menu below.'; } $options = array_map(fn (array $backup) => Ui::option( (string) $backup['uuid'], (string) ($backup['name'] ?: 'Backup'), self::summary($backup), ), $backups); $components = [ $notice === null ? null : Ui::text($notice), Ui::section(implode("\n", [ '## Backups', Format::name($server['name']) . ' · **' . $count . '** of ' . ($limit > 0 ? $limit : 'unlimited') . ' used', $full ? '-# Every slot is used. Delete or unlock an old one to make room; the oldest unlocked backup is replaced otherwise.' : '-# Locked backups cannot be deleted, not even by the panel rotating old ones out.', ]), Ui::thumbnail($style->logo(Servers::logo($server)))), Ui::divider(), Ui::text($lines === [] ? "**No backups yet.**\nPress **Create backup** to take the first one." : implode("\n", $lines)), $options === [] ? null : Ui::row([Ui::select("dzb:bks:{$id}", 'Manage a backup…', $options)]), Ui::row([ Ui::button("dzb:bkn:{$id}", 'Create backup', Ui::SUCCESS, $limit === 0), Ui::button("dzb:bk:{$id}", 'Refresh', Ui::SECONDARY), ...self::back($id), Ui::link(Servers::panelUrl($server, 'backups'), 'Panel'), ]), Ui::text('-# ' . ($limit === 0 ? 'This server is not allowed any backups. The limit is set by the host. · ' : '') . $style->footer()), ]; return Ui::message([Ui::container($components, $style->accent())]); } public static function detail(ClientApi $api, string $identifier, string $uuid, ?string $notice = null, bool $confirmDelete = false, ?string $download = null): array { $found = Servers::find($api, $identifier); if ($found['server'] === null) { return Cards::error($found['error']); } $server = $found['server']; if (preg_match('/^[0-9a-f-]{36}$/i', $uuid) !== 1) { return self::list($api, $server['id'], 'That backup could not be found.'); } $response = $api->get('servers/' . $server['id'] . '/backups/' . $uuid); if (!$response->ok()) { return self::list($api, $server['id'], $response->error()); } return self::composeDetail($server, $response->attributes(), $notice, $confirmDelete, $download); } public static function composeDetail(array $server, array $backup, ?string $notice = null, bool $confirmDelete = false, ?string $download = null): array { $style = Style::current(); $id = $server['id']; $uuid = (string) ($backup['uuid'] ?? ''); $locked = (bool) ($backup['is_locked'] ?? false); $done = ($backup['completed_at'] ?? null) !== null; $success = (bool) ($backup['is_successful'] ?? false); $facts = [ '**Status** ' . (!$done ? 'Still being made' : ($success ? 'Complete' : 'Failed')), '**Size** ' . ($done ? Format::bytes((int) ($backup['bytes'] ?? 0)) : '–'), '**Started** ' . Format::timestamp($backup['created_at'] ?? null, 'f') . ' · ' . Format::timestamp($backup['created_at'] ?? null), '**Finished** ' . ($done ? Format::timestamp($backup['completed_at'], 'f') : '–'), '**Locked** ' . ($locked ? 'Yes, it cannot be deleted' : 'No'), ]; $checksum = $backup['checksum'] ?? null; if (is_array($checksum)) { $checksum = (string) ($checksum['checksum'] ?? $checksum['value'] ?? ''); } $checksum = trim((string) $checksum); if ($checksum !== '') { $facts[] = '**Checksum** ' . Format::code(Ui::clip($checksum, 70)); } $ignored = trim((string) ($backup['ignored_files'] ?? '')); if ($ignored !== '') { $facts[] = '**Ignored** ' . Format::code(Ui::clip(str_replace("\n", ', ', $ignored), 120)); } $actions = $confirmDelete ? [ Ui::button("dzb:bkx:{$id}:{$uuid}", 'Yes, delete it', Ui::DANGER), Ui::button("dzb:bkv:{$id}:{$uuid}", 'Cancel', Ui::SECONDARY), ] : [ Ui::button("dzb:bkl:{$id}:{$uuid}", $locked ? 'Unlock' : 'Lock', $locked ? Ui::SECONDARY : Ui::PRIMARY, !$done), $download === null ? Ui::button("dzb:bkg:{$id}:{$uuid}", 'Download link', Ui::SECONDARY, !$done || !$success) : Ui::link($download, 'Download now'), Ui::button("dzb:bkd:{$id}:{$uuid}", 'Delete', Ui::DANGER, $locked || !$done), Ui::button("dzb:bk:{$id}", 'All backups', Ui::SECONDARY), ]; $components = [ $notice === null ? null : Ui::text($notice), Ui::section([ '## ' . Format::name((string) ($backup['name'] ?: 'Backup'), 70), implode("\n", $facts), '-# ' . Format::name($server['name']) . ' · ' . Format::code($uuid), ], Ui::thumbnail($style->logo(Servers::logo($server)))), $confirmDelete ? Ui::text("### Delete this backup?\nIt is removed from the node straight away and cannot be brought back.") : null, $download === null ? null : Ui::text('-# The download link works for a few minutes and only for this backup.'), Ui::row($actions), ]; return Ui::message([Ui::container($components, $locked ? Ui::PENDING : $style->accent())]); } public static function createModal(string $identifier): array { return Ui::modal("dzb:bkm:{$identifier}", 'Create a backup', [ Ui::input('name', 'Name', false, false, 191, 'Before the 1.21 update'), Ui::input('ignored', 'Files to leave out', true, false, 2000, "logs/\n*.tmp"), ]); } private static function back(string $id): array { return Style::can('controlpanel') ? [Ui::button("dzb:cp:{$id}", 'Control panel', Ui::SECONDARY)] : []; } private static function line(array $backup): string { return '**' . Format::name((string) ($backup['name'] ?: 'Backup'), 50) . '** · ' . self::summary($backup, true) . (($backup['is_locked'] ?? false) ? ' · locked' : ''); } private static function summary(array $backup, bool $rich = false): string { if (($backup['completed_at'] ?? null) === null) { return 'in progress'; } if (!($backup['is_successful'] ?? false)) { return 'failed'; } $when = $rich ? Format::timestamp($backup['created_at'] ?? null) : (Format::time($backup['created_at'] ?? null)?->diffForHumans() ?? ''); return trim(Format::bytes((int) ($backup['bytes'] ?? 0)) . ' · ' . $when, ' ·'); } } 